_COL = {"Black":"noir","Blue":"bleu","Green":"vert","Red":"rouge","White":"blanc","Brass":"d'airain","Bronze":"de bronze","Copper":"de cuivre","Gold":"d'or","Silver":"d'argent"}
_SW = {"Bats":"chauves-souris","Insects":"insectes","Poisonous Snakes":"serpents venimeux","Quippers":"quippers","Ravens":"corbeaux","Rats":"rats","Beasts":"bêtes"}
def fr_name(n):
    if n in NAMES: return NAMES[n]
    import re
    m = re.match(r"^(Ancient|Adult|Young|) ?(\w+) Dragon( Wyrmling)?$", n)
    if m and m.group(2) in _COL:
        c = _COL[m.group(2)]
        if m.group(3): return f"Dragonnet {c}"
        return {"Ancient":f"Dragon {c} antique","Adult":f"Dragon {c} adulte","Young":f"Jeune dragon {c}"}.get(m.group(1), f"Dragon {c}")
    m = re.match(r"^Swarm of (?:Tiny )?(.+)$", n)
    if m and m.group(1) in _SW: return f"Nuée de {_SW[m.group(1)]}"
    return n
